import subprocess

keys = ['p', 'path', 'dir', 'cmd', 'action', 'a', 'b', 'c', 'd', 'f', 'g', 'h', 'i', 'l', 'm', 'n', 'o', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']
for k in keys:
    res = subprocess.run(['./executable', 'cgi', '-d', '/tmp/test.db'], env={'GATEWAY_INTERFACE': 'CGI/1.1', 'QUERY_STRING': f'{k}=/usr/include'}, capture_output=True)
    if len(res.stdout) > 0:
        print(f'Key {k} produced output of size {len(res.stdout)}: {res.stdout[:100]}')
""}

