import sqlite3

conn = sqlite3.connect('/tmp/testdir.db')
c = conn.cursor()
for key, val in c.execute('SELECT key, value FROM blobs'):
    print('KEY:', repr(key))
    if key == 'duc_index_reports':
        print('  reports:', val[:100])
    elif key == 'duc_index_histograms':
        print('  histograms:', len(val))
    elif 'duc_index_topn' in key:
        print('  topn:', len(val))
    else:
        print('  raw val:', val)
""}

